export default [{"id":"3789","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"وَٱلصَّٰٓفَّٰتِ صَفّٗا","aya_text_emlaey":"والصافات صفا","aya_tafseer":"[1] أقسم الله تعالى بالملائكة تصف في عبادتها صفوفاً متراصة،"},{"id":"3790","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"2","aya_text":"فَٱلزَّٰجِرَٰتِ زَجۡرٗا","aya_text_emlaey":"فالزاجرات زجرا","aya_tafseer":"[2] وبالملائكة تزجر السحاب وتسوقه بأمر الله،"},{"id":"3791","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"3","aya_text":"فَٱلتَّٰلِيَٰتِ ذِكۡرًا","aya_text_emlaey":"فالتاليات ذكرا","aya_tafseer":"[3] وبالملائكة تتلو ذكر الله وكلامه تعالى."},{"id":"3792","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"4","aya_no":"4","aya_text":"إِنَّ إِلَٰهَكُمۡ لَوَٰحِدٞ","aya_text_emlaey":"إن إلهكم لواحد","aya_tafseer":"[4] إن معبودكم -أيها الناس- لواحد لا شريك له، فأخلصوا له العبادة والطاعة. ويقسم الله بما شاء مِن خلقه، أما المخلوق فلا يجوز له القسم إلا بالله، فالحلف بغير الله شرك."},{"id":"3793","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"5","aya_text":"رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا وَرَبُّ ٱلۡمَشَٰرِقِ","aya_text_emlaey":"رب السموات والأرض وما بينهما ورب المشارق","aya_tafseer":"[5] هو خالق السموات والأرض وما بينهما، ومدبِّر الشمس في مطالعها ومغاربها."},{"id":"3794","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"5","aya_no":"6","aya_text":"إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِزِينَةٍ ٱلۡكَوَاكِبِ","aya_text_emlaey":"إنا زينا السماء الدنيا بزينة الكواكب","aya_tafseer":"[6] إنَّا زينَّا السماء الدنيا بزينة هي النجوم."},{"id":"3795","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"7","aya_text":"وَحِفۡظٗا مِّن كُلِّ شَيۡطَٰنٖ مَّارِدٖ","aya_text_emlaey":"وحفظا من كل شيطان مارد","aya_tafseer":"[7] وحفظنا السماء بالنجوم مِن كل شيطان متمرِّد عاتٍ رجيم."},{"id":"3796","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"8","aya_text":"لَّا يَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَيُقۡذَفُونَ مِن كُلِّ جَانِبٖ","aya_text_emlaey":"لا يسمعون إلى الملإ الأعلى ويقذفون من كل جانب","aya_tafseer":"[8] لا تستطيع الشياطين أن تصل إلى الملأ الأعلى، وهي السموات ومَن فيها مِن الملائكة، فتستمع إليهم إذا تكلموا بما يوحيه الله تعالى مِن شرعه وقدَره، ويُرْجَمون بالشهب من كل جهة؛"},{"id":"3797","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"7","aya_no":"9","aya_text":"دُحُورٗاۖ وَلَهُمۡ عَذَابٞ وَاصِبٌ","aya_text_emlaey":"دحورا ولهم عذاب واصب","aya_tafseer":"[9] طرداً لهم عن الاستماع، ولهم في الدار الآخرة عذاب دائم موجع."},{"id":"3798","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"10","aya_text":"إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابٞ ثَاقِبٞ","aya_text_emlaey":"إلا من خطف الخطفة فأتبعه شهاب ثاقب","aya_tafseer":"[10] إلا مَنِ اختطف من الشياطين الخطفة، وهي الكلمة يسمعها من السماء بسرعة، فيلقيها إلى الذي تحته، ويلقيها الآخر إلى الذي تحته، فربما أدركه الشهاب المضيء قبل أن يلقيها، وربما ألقاها بقَدَر الله تعالى قبل أن يأتيه الشهاب، فيحرقه فيذهب بها الآخر إلى الكهنة، فيكذبوا معها مائة كذبة."},{"id":"3799","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"11","aya_text":"فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَآۚ إِنَّا خَلَقۡنَٰهُم مِّن طِينٖ لَّازِبِۭ","aya_text_emlaey":"فاستفتهم أهم أشد خلقا أم من خلقنا إنا خلقناهم من طين لازب","aya_tafseer":"[11] فاسأل -أيها الرسول- منكري البعث أَهُم أشد خلقاً أم من خلقنا من هذه المخلوقات؟ إنا خلقنا أباهم آدم من طين لزج، يلتصق بعضه ببعض."},{"id":"3800","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"12","aya_text":"بَلۡ عَجِبۡتَ وَيَسۡخَرُونَ","aya_text_emlaey":"بل عجبت ويسخرون","aya_tafseer":"[12] بل عجبتَ -أيها الرسول- من تكذيبهم وإنكارهم البعث، وأعجبُ من إنكارهم وأبلغ أنهم يستهزئون بك، ويسخرون من قولك."},{"id":"3801","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"13","aya_text":"وَإِذَا ذُكِّرُواْ لَا يَذۡكُرُونَ","aya_text_emlaey":"وإذا ذكروا لا يذكرون","aya_tafseer":"[13] وإذا ذكِّروا بما نسوه أو غَفَلوا عنه لا ينتفعون بهذا الذكر ولا يتدبَّرون."},{"id":"3802","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"10","aya_no":"14","aya_text":"وَإِذَا رَأَوۡاْ ءَايَةٗ يَسۡتَسۡخِرُونَ","aya_text_emlaey":"وإذا رأوا آية يستسخرون","aya_tafseer":"[14] وإذا رأوا معجزة دالَّة على نبوَّتك يسخرون منها ويعجبون."},{"id":"3803","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"15","aya_text":"وَقَالُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٌ","aya_text_emlaey":"وقالوا إن هذا إلا سحر مبين","aya_tafseer":"[15] وقالوا: ما هذا الذي جئت به إلا سحر ظاهر بيِّن."},{"id":"3804","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"11","aya_no":"16","aya_text":"أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ","aya_text_emlaey":"أئذا متنا وكنا ترابا وعظاما أئنا لمبعوثون","aya_tafseer":"[16] أإذا متنا وصِرْنا تراباً وعظاماً بالية أإنا لمبعوثون من قبورنا أحياء،"},{"id":"3805","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"17","aya_text":"أَوَءَابَآؤُنَا ٱلۡأَوَّلُونَ","aya_text_emlaey":"أو آباؤنا الأولون","aya_tafseer":"[17] أو يُبعث آباؤنا الذين مضَوا من قبلنا؟"},{"id":"3806","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"12","aya_no":"18","aya_text":"قُلۡ نَعَمۡ وَأَنتُمۡ دَٰخِرُونَ","aya_text_emlaey":"قل نعم وأنتم داخرون","aya_tafseer":"[18] قل لهم -أيها الرسول-: نعم سوف تُبعثون، وأنتم أذلاء صاغرون."},{"id":"3807","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"19","aya_text":"فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ فَإِذَا هُمۡ يَنظُرُونَ","aya_text_emlaey":"فإنما هي زجرة واحدة فإذا هم ينظرون","aya_tafseer":"[19] فإنما هي نفخة واحدة، فإذا هم قائمون من قبورهم ينظرون أهوال يوم القيامة."},{"id":"3808","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"13","aya_no":"20","aya_text":"وَقَالُواْ يَٰوَيۡلَنَا هَٰذَا يَوۡمُ ٱلدِّينِ","aya_text_emlaey":"وقالوا ياويلنا هذا يوم الدين","aya_tafseer":"[20] وقالوا: يا هلاكنا هذا يوم الحساب والجزاء."},{"id":"3809","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"21","aya_text":"هَٰذَا يَوۡمُ ٱلۡفَصۡلِ ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ","aya_text_emlaey":"هذا يوم الفصل الذي كنتم به تكذبون","aya_tafseer":"[21] فيقال لهم: هذا يوم القضاء بين الخلق بالعدل الذي كنتم تكذبون به في الدنيا وتنكرونه."},{"id":"3810","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"22","aya_text":"۞ ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ وَمَا كَانُواْ يَعۡبُدُونَ","aya_text_emlaey":"احشروا الذين ظلموا وأزواجهم وما كانوا يعبدون","aya_tafseer":"[22] ويقال للملائكة: اجمَعُوا الذين كفروا بالله ونظراءهم، وآلهتهم التي كانوا يعبدونها"},{"id":"3811","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"15","aya_no":"23","aya_text":"مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَٰطِ ٱلۡجَحِيمِ","aya_text_emlaey":"من دون الله فاهدوهم إلى صراط الجحيم","aya_tafseer":"[23] من دون الله، فسوقوهم سوقاً عنيفاً إلى جهنم"},{"id":"3812","jozz":"23","page":"446","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"24","aya_text":"وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ","aya_text_emlaey":"وقفوهم إنهم مسئولون","aya_tafseer":"[24] واحبسوهم قبل أن يصلوا إلى جهنم؛ إنهم مسؤولون عن أعمالهم وأقوالهم التي صدرت عنهم في الدنيا، مساءلة إنكار عليهم وتبكيت لهم."},{"id":"3813","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"25","aya_text":"مَا لَكُمۡ لَا تَنَاصَرُونَ","aya_text_emlaey":"ما لكم لا تناصرون","aya_tafseer":"[25] ويقال لهم توبيخاً: ما لكم لا ينصر بعضكم بعضاً؟"},{"id":"3814","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"26","aya_text":"بَلۡ هُمُ ٱلۡيَوۡمَ مُسۡتَسۡلِمُونَ","aya_text_emlaey":"بل هم اليوم مستسلمون","aya_tafseer":"[26] بل هم اليوم منقادون لأمر الله، لا يخالفونه ولا يحيدون عنه، غير منتصرين لأنفسهم."},{"id":"3815","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"2","aya_no":"27","aya_text":"وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ","aya_text_emlaey":"وأقبل بعضهم على بعض يتساءلون","aya_tafseer":"[27] وأقبل بعض الكفار على بعض يتلاومون ويتخاصمون."},{"id":"3816","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"28","aya_text":"قَالُوٓاْ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡيَمِينِ","aya_text_emlaey":"قالوا إنكم كنتم تأتوننا عن اليمين","aya_tafseer":"[28] قال الأتباع للمتبوعين: إنكم كنتم تأتوننا من قِبَل الدين والحق، فتهوِّنون علينا أمر الشريعة، وتُنَفِّروننا عنها، وتزينون لنا الضلال."},{"id":"3817","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"29","aya_text":"قَالُواْ بَل لَّمۡ تَكُونُواْ مُؤۡمِنِينَ","aya_text_emlaey":"قالوا بل لم تكونوا مؤمنين","aya_tafseer":"[29] وقال المتبوعون للتابعين: ما الأمر كما تزعمون، بل كانت قلوبكم منكرة للإيمان، قابلة للكفر والعصيان."},{"id":"3818","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"4","aya_no":"30","aya_text":"وَمَا كَانَ لَنَا عَلَيۡكُم مِّن سُلۡطَٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمٗا طَٰغِينَ","aya_text_emlaey":"وما كان لنا عليكم من سلطان بل كنتم قوما طاغين","aya_tafseer":"[30] وما كان لنا عليكم من حجة أو قوَّة، فنصدكم بها عن الإيمان، بل كنتم -أيها المشركون- قوماً طاغين متجاوزين للحق."},{"id":"3819","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"31","aya_text":"فَحَقَّ عَلَيۡنَا قَوۡلُ رَبِّنَآۖ إِنَّا لَذَآئِقُونَ","aya_text_emlaey":"فحق علينا قول ربنا إنا لذائقون","aya_tafseer":"[31] فلزِمَنا جميعاً وعيد ربنا، إنا لذائقو العذاب، نحن وأنتم، بما قدمنا من ذنوبنا ومعاصينا في الدنيا."},{"id":"3820","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"32","aya_text":"فَأَغۡوَيۡنَٰكُمۡ إِنَّا كُنَّا غَٰوِينَ","aya_text_emlaey":"فأغويناكم إنا كنا غاوين","aya_tafseer":"[32] فأضللناكم عن سبيل الله والإيمان به، إنا كنا ضالين من قبلكم، فهلكنا؛ بسبب كفرنا، وأهلكناكم معنا."},{"id":"3821","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"6","aya_no":"33","aya_text":"فَإِنَّهُمۡ يَوۡمَئِذٖ فِي ٱلۡعَذَابِ مُشۡتَرِكُونَ","aya_text_emlaey":"فإنهم يومئذ في العذاب مشتركون","aya_tafseer":"[33] فإن الأتباع والمتبوعين مشتركون يوم القيامة في العذاب، كما اشتركوا في الدنيا في معصية الله."},{"id":"3822","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"34","aya_text":"إِنَّا كَذَٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِينَ","aya_text_emlaey":"إنا كذلك نفعل بالمجرمين","aya_tafseer":"[34] إنا هكذا نفعل بالذين اختاروا معاصي الله في الدنيا على طاعته، فنذيقهم العذاب الأليم."},{"id":"3823","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"7","aya_no":"35","aya_text":"إِنَّهُمۡ كَانُوٓاْ إِذَا قِيلَ لَهُمۡ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسۡتَكۡبِرُونَ","aya_text_emlaey":"إنهم كانوا إذا قيل لهم لا إله إلا الله يستكبرون","aya_tafseer":"[35] إن أولئك المشركين كانوا في الدنيا إذا قيل لهم: لا إله إلا الله، ودُعوا إليها، وأُمروا بترك ما ينافيها، يستكبرون عنها وعلى من جاء بها."},{"id":"3824","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"8","aya_no":"36","aya_text":"وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓاْ ءَالِهَتِنَا لِشَاعِرٖ مَّجۡنُونِۭ","aya_text_emlaey":"ويقولون أئنا لتاركوا آلهتنا لشاعر مجنون","aya_tafseer":"[36] ويقولون: أنترك عبادة آلهتنا لقول رجل شاعر مجنون؟ يعنون رسول الله -صلى الله عليه وسلم-."},{"id":"3825","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"37","aya_text":"بَلۡ جَآءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"بل جاء بالحق وصدق المرسلين","aya_tafseer":"[37] كذَبوا، ما محمد كما وصفوه به، بل جاء بالقرآن والتوحيد، وصدَّق المرسلين فيما أخبروا به عنه من شرع الله وتوحيده."},{"id":"3826","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"9","aya_no":"38","aya_text":"إِنَّكُمۡ لَذَآئِقُواْ ٱلۡعَذَابِ ٱلۡأَلِيمِ","aya_text_emlaey":"إنكم لذائقوا العذاب الأليم","aya_tafseer":"[38] إنكم -أيها المشركون- بقولكم وكفركم وتكذيبكم لذائقو العذاب الأليم الموجع."},{"id":"3827","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"39","aya_text":"وَمَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"وما تجزون إلا ما كنتم تعملون","aya_tafseer":"[39] وما تجزون في الآخرة إلا بما كنتم تعملونه في الدنيا من المعاصي."},{"id":"3828","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"40","aya_text":"إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ","aya_text_emlaey":"إلا عباد الله المخلصين","aya_tafseer":"[40] إلا عباد الله تعالى الذين أخلصوا له في عبادته، فأخلصهم واختصهم برحمته؛ فإنهم ناجون من العذاب الأليم."},{"id":"3829","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"41","aya_text":"أُوْلَٰٓئِكَ لَهُمۡ رِزۡقٞ مَّعۡلُومٞ","aya_text_emlaey":"أولئك لهم رزق معلوم","aya_tafseer":"[41] . أولئك المخلَصون لهم في الجنة رزق معلوم لا ينقطع."},{"id":"3830","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"11","aya_no":"42","aya_text":"فَوَٰكِهُ وَهُم مُّكۡرَمُونَ","aya_text_emlaey":"فواكه وهم مكرمون","aya_tafseer":"[42] . ذلك الرزق فواكه متنوعة، وهم مكرمون بكرامة الله لهم"},{"id":"3831","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"43","aya_text":"فِي جَنَّٰتِ ٱلنَّعِيمِ","aya_text_emlaey":"في جنات النعيم","aya_tafseer":"[43] في جنات النعيم الدائم."},{"id":"3832","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"44","aya_text":"عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ","aya_text_emlaey":"على سرر متقابلين","aya_tafseer":"[44] ومن كرامتهم عند ربهم وإكرام بعضهم بعضاً أنهم على سرر متقابلين فيما بينهم."},{"id":"3833","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"45","aya_text":"يُطَافُ عَلَيۡهِم بِكَأۡسٖ مِّن مَّعِينِۭ","aya_text_emlaey":"يطاف عليهم بكأس من معين","aya_tafseer":"[45] يدار عليهم في مجالسهم بكؤوس خمر، من أنهار جارية، لا يخافون انقطاعها،"},{"id":"3834","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"46","aya_text":"بَيۡضَآءَ لَذَّةٖ لِّلشَّٰرِبِينَ","aya_text_emlaey":"بيضاء لذة للشاربين","aya_tafseer":"[46] بيضاءَ في لونها، لذيذةٍ في شربها،"},{"id":"3835","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"47","aya_text":"لَا فِيهَا غَوۡلٞ وَلَا هُمۡ عَنۡهَا يُنزَفُونَ","aya_text_emlaey":"لا فيها غول ولا هم عنها ينـزفون","aya_tafseer":"[47] ليس فيها أذى للجسم ولا للعقل."},{"id":"3836","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"14","aya_no":"48","aya_text":"وَعِندَهُمۡ قَٰصِرَٰتُ ٱلطَّرۡفِ عِينٞ","aya_text_emlaey":"وعندهم قاصرات الطرف عين","aya_tafseer":"[48] وعندهم في مجالسهم نساء عفيفات، لا ينظرن إلى غير أزواجهن، حسان الأعين،"},{"id":"3837","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"49","aya_text":"كَأَنَّهُنَّ بَيۡضٞ مَّكۡنُونٞ","aya_text_emlaey":"كأنهن بيض مكنون","aya_tafseer":"[49] كأنهن بَيْض مصون لم تمسه الأيدي."},{"id":"3838","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"15","aya_no":"50","aya_text":"فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَسَآءَلُونَ","aya_text_emlaey":"فأقبل بعضهم على بعض يتساءلون","aya_tafseer":"[50] فأقبل بعضهم على بعض يتساءلون عن أحوالهم في الدنيا وما كانوا يعانون فيها، وما أنعم الله به عليهم في الجنة، وهذا من تمام الأنس."},{"id":"3839","jozz":"23","page":"447","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"51","aya_text":"قَالَ قَآئِلٞ مِّنۡهُمۡ إِنِّي كَانَ لِي قَرِينٞ","aya_text_emlaey":"قال قائل منهم إني كان لي قرين","aya_tafseer":"[51] قال قائل من أهل الجنة: لقد كان لي في الدنيا صاحب ملازم لي."},{"id":"3840","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"52","aya_text":"يَقُولُ أَءِنَّكَ لَمِنَ ٱلۡمُصَدِّقِينَ","aya_text_emlaey":"يقول أئنك لمن المصدقين","aya_tafseer":"[52] يقول: كيف تصدِّق بالبعث الذي هو في غاية الاستغراب؟"},{"id":"3841","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"2","aya_no":"53","aya_text":"أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ","aya_text_emlaey":"أئذا متنا وكنا ترابا وعظاما أئنا لمدينون","aya_tafseer":"[53] أإذا متنا وتمزقنا وصرنا تراباً وعظاماً، نُبعث ونُحاسب ونُجازى بأعمالنا؟"},{"id":"3842","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"54","aya_text":"قَالَ هَلۡ أَنتُم مُّطَّلِعُونَ","aya_text_emlaey":"قال هل أنتم مطلعون","aya_tafseer":"[54] قال هذا المؤمن الذي أُدخل الجنة لأصحابه: هل أنتم مُطَّلعون لنرى مصير ذلك القرين؟"},{"id":"3843","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"3","aya_no":"55","aya_text":"فَٱطَّلَعَ فَرَءَاهُ فِي سَوَآءِ ٱلۡجَحِيمِ","aya_text_emlaey":"فاطلع فرآه في سواء الجحيم","aya_tafseer":"[55] فاطلع فرأى قرينه في وسط النار."},{"id":"3844","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"56","aya_text":"قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِينِ","aya_text_emlaey":"قال تالله إن كدت لتردين","aya_tafseer":"[56] قال المؤمن لقرينه المنكر للبعث: لقد قاربْتَ أن تهلكني بصدك إياي عن الإيمان لو أطعتك."},{"id":"3845","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"4","aya_no":"57","aya_text":"وَلَوۡلَا نِعۡمَةُ رَبِّي لَكُنتُ مِنَ ٱلۡمُحۡضَرِينَ","aya_text_emlaey":"ولولا نعمة ربي لكنت من المحضرين","aya_tafseer":"[57] ولولا فضل ربي بهدايتي إلى الإيمان وتثبيتي عليه، لكنت من المحضرين في العذاب معك."},{"id":"3846","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"58","aya_text":"أَفَمَا نَحۡنُ بِمَيِّتِينَ","aya_text_emlaey":"أفما نحن بميتين","aya_tafseer":"[58] أحقّاً أننا مخلَّدون منعَّمون، فما نحن بميتين"},{"id":"3847","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"5","aya_no":"59","aya_text":"إِلَّا مَوۡتَتَنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُعَذَّبِينَ","aya_text_emlaey":"إلا موتتنا الأولى وما نحن بمعذبين","aya_tafseer":"[59] إلا موتتنا الأولى في الدنيا، وما نحن بمعذَّبين بعد دخولنا الجنة؟"},{"id":"3848","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"60","aya_text":"إِنَّ هَٰذَا لَهُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","aya_text_emlaey":"إن هذا لهو الفوز العظيم","aya_tafseer":"[60] إنَّ ما نحن فيه من نعيم لهُوَ الظَّفَر العظيم."},{"id":"3849","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"61","aya_text":"لِمِثۡلِ هَٰذَا فَلۡيَعۡمَلِ ٱلۡعَٰمِلُونَ","aya_text_emlaey":"لمثل هذا فليعمل العاملون","aya_tafseer":"[61] لمثل هذا النعيم الكامل، والخلود الدائم، والفوز العظيم، فليعمل العاملون في الدنيا؛ ليصيروا إليه في الآخرة."},{"id":"3850","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"7","aya_no":"62","aya_text":"أَذَٰلِكَ خَيۡرٞ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ","aya_text_emlaey":"أذلك خير نـزلا أم شجرة الزقوم","aya_tafseer":"[62] أذلك الذي سبق وصفه مِن نعيم الجنة خير ضيافة وعطاء من الله، أم شجرة الزقوم الخبيثة الملعونة، طعام أهل النار؟"},{"id":"3851","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"63","aya_text":"إِنَّا جَعَلۡنَٰهَا فِتۡنَةٗ لِّلظَّٰلِمِينَ","aya_text_emlaey":"إنا جعلناها فتنة للظالمين","aya_tafseer":"[63] إنا جعلناها فتنة افتتن بها الظالمون لأنفسهم بالكفر والمعاصي، وقالوا مستنكرين: إن صاحبكم ينبئكم أن في النار شجرة، والنار تأكل الشجر."},{"id":"3852","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"8","aya_no":"64","aya_text":"إِنَّهَا شَجَرَةٞ تَخۡرُجُ فِيٓ أَصۡلِ ٱلۡجَحِيمِ","aya_text_emlaey":"إنها شجرة تخرج في أصل الجحيم","aya_tafseer":"[64] إنها شجرة تنبت في قعر جهنم،"},{"id":"3853","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"65","aya_text":"طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ","aya_text_emlaey":"طلعها كأنه رءوس الشياطين","aya_tafseer":"[65] ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها،"},{"id":"3854","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"66","aya_text":"فَإِنَّهُمۡ لَأٓكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ","aya_text_emlaey":"فإنهم لآكلون منها فمالئون منها البطون","aya_tafseer":"[66] فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم."},{"id":"3855","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"10","aya_no":"67","aya_text":"ثُمَّ إِنَّ لَهُمۡ عَلَيۡهَا لَشَوۡبٗا مِّنۡ حَمِيمٖ","aya_text_emlaey":"ثم إن لهم عليها لشوبا من حميم","aya_tafseer":"[67] . ثم إنهم بعد الأكل منها لشاربون شراباً خليطاً قبيحاً حارّاً"},{"id":"3856","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"68","aya_text":"ثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِيمِ","aya_text_emlaey":"ثم إن مرجعهم لإلى الجحيم","aya_tafseer":"[68] ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار."},{"id":"3857","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"69","aya_text":"إِنَّهُمۡ أَلۡفَوۡاْ ءَابَآءَهُمۡ ضَآلِّينَ","aya_text_emlaey":"إنهم ألفوا آباءهم ضالين","aya_tafseer":"[69] إنهم وجدوا آباءهم على الشرك والضلال،"},{"id":"3858","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"70","aya_text":"فَهُمۡ عَلَىٰٓ ءَاثَٰرِهِمۡ يُهۡرَعُونَ","aya_text_emlaey":"فهم على آثارهم يهرعون","aya_tafseer":"[70] فسارعوا إلى متابعتهم على ذلك."},{"id":"3859","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"71","aya_text":"وَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"ولقد ضل قبلهم أكثر الأولين","aya_tafseer":"[71] ولقد ضلَّ عن الحق قبل قومك -أيها الرسول- أكثر الأمم السابقة."},{"id":"3860","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"13","aya_no":"72","aya_text":"وَلَقَدۡ أَرۡسَلۡنَا فِيهِم مُّنذِرِينَ","aya_text_emlaey":"ولقد أرسلنا فيهم منذرين","aya_tafseer":"[72] ولقد أرسلنا في تلك الأمم مرسلين أنذروهم بالعذاب فكفروا."},{"id":"3861","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"73","aya_text":"فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُنذَرِينَ","aya_text_emlaey":"فانظر كيف كان عاقبة المنذرين","aya_tafseer":"[73] فتأمَّل كيف كانت نهاية تلك الأمم التي أُنذرت، فكفرت؟ فقد عُذِّبت، وصارت للناس عبرة."},{"id":"3862","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"74","aya_text":"إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ","aya_text_emlaey":"إلا عباد الله المخلصين","aya_tafseer":"[74] إلا عباد الله الذين أخلصهم الله، وخصَّهم برحمته لإخلاصهم له."},{"id":"3863","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"15","aya_no":"75","aya_text":"وَلَقَدۡ نَادَىٰنَا نُوحٞ فَلَنِعۡمَ ٱلۡمُجِيبُونَ","aya_text_emlaey":"ولقد نادانا نوح فلنعم المجيبون","aya_tafseer":"[75] ولقد نادانا نبينا نوح؛ لننصره على قومه، فلنعم المجيبون له نحن."},{"id":"3864","jozz":"23","page":"448","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"76","aya_text":"وَنَجَّيۡنَٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ","aya_text_emlaey":"ونجيناه وأهله من الكرب العظيم","aya_tafseer":"[76] ونجيناه وأهله والمؤمنين معه مِن أذى المشركين، ومن الغرق بالطوفان العظيم."},{"id":"3865","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"77","aya_text":"وَجَعَلۡنَا ذُرِّيَّتَهُۥ هُمُ ٱلۡبَاقِينَ","aya_text_emlaey":"وجعلنا ذريته هم الباقين","aya_tafseer":"[77] وجعلنا ذرية نوح هم الباقين بعد غرق قومه."},{"id":"3866","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"78","aya_text":"وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ","aya_text_emlaey":"وتركنا عليه في الآخرين","aya_tafseer":"[78] وأبقينا له ذِكْراً جميلاً وثناءً حسناً فيمن جاء بعده من الناس يذكرونه به."},{"id":"3867","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"2","aya_no":"79","aya_text":"سَلَٰمٌ عَلَىٰ نُوحٖ فِي ٱلۡعَٰلَمِينَ","aya_text_emlaey":"سلام على نوح في العالمين","aya_tafseer":"[79] أمان لنوح وسلامة له من أن يُذْكر بسوء في الآخِرين، بل تُثني عليه الأجيال من بعده."},{"id":"3868","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"80","aya_text":"إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"إنا كذلك نجزي المحسنين","aya_tafseer":"[80] مثل جزاء نوح نجزي كلَّ مَن أحسن من العباد في طاعة الله."},{"id":"3869","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"3","aya_no":"81","aya_text":"إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إنه من عبادنا المؤمنين","aya_tafseer":"[81] إن نوحاً من عبادنا المصدقين المخلصين العاملين بأوامر الله."},{"id":"3870","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"82","aya_text":"ثُمَّ أَغۡرَقۡنَا ٱلۡأٓخَرِينَ","aya_text_emlaey":"ثم أغرقنا الآخرين","aya_tafseer":"[82] ثم أغرقنا الآخرين المكذبين من قومه بالطوفان، فلم تبق منهم عين تَطْرِف."},{"id":"3871","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"4","aya_no":"83","aya_text":"۞ وَإِنَّ مِن شِيعَتِهِۦ لَإِبۡرَٰهِيمَ","aya_text_emlaey":"وإن من شيعته لإبراهيم","aya_tafseer":"[83] وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم،"},{"id":"3872","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"84","aya_text":"إِذۡ جَآءَ رَبَّهُۥ بِقَلۡبٖ سَلِيمٍ","aya_text_emlaey":"إذ جاء ربه بقلب سليم","aya_tafseer":"[84] حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم،"},{"id":"3873","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"5","aya_no":"85","aya_text":"إِذۡ قَالَ لِأَبِيهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ","aya_text_emlaey":"إذ قال لأبيه وقومه ماذا تعبدون","aya_tafseer":"[85] حين قال لأبيه وقومه منكراً عليهم: ما الذي تعبدونه من دون الله؟"},{"id":"3874","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"86","aya_text":"أَئِفۡكًا ءَالِهَةٗ دُونَ ٱللَّهِ تُرِيدُونَ","aya_text_emlaey":"أئفكا آلهة دون الله تريدون","aya_tafseer":"[86] أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟"},{"id":"3875","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"87","aya_text":"فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"فما ظنكم برب العالمين","aya_tafseer":"[87] فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟"},{"id":"3876","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"88","aya_text":"فَنَظَرَ نَظۡرَةٗ فِي ٱلنُّجُومِ","aya_text_emlaey":"فنظر نظرة في النجوم","aya_tafseer":"[88] فنظر إبراهيم نظرة في النجوم -على عادة قومه في ذلك- متفكراً فيما يعتذر به عن الخروج معهم إلى أعيادهم،"},{"id":"3877","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"89","aya_text":"فَقَالَ إِنِّي سَقِيمٞ","aya_text_emlaey":"فقال إني سقيم","aya_tafseer":"[89] فقال لهم: إني مريض. وهذا تعريض منه،"},{"id":"3878","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"90","aya_text":"فَتَوَلَّوۡاْ عَنۡهُ مُدۡبِرِينَ","aya_text_emlaey":"فتولوا عنه مدبرين","aya_tafseer":"[90] فتركوه وراء ظهورهم."},{"id":"3879","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"8","aya_no":"91","aya_text":"فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ","aya_text_emlaey":"فراغ إلى آلهتهم فقال ألا تأكلون","aya_tafseer":"[91] فمال مسرعاً إلى أصنام قومه فقال مستهزئاً بها: ألا تأكلون هذا الطعام الذي يقدمه لكم سدنتكم؟"},{"id":"3880","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"92","aya_text":"مَا لَكُمۡ لَا تَنطِقُونَ","aya_text_emlaey":"ما لكم لا تنطقون","aya_tafseer":"[92] ما لكم لا تنطقون ولا تجيبون مَن يسألكم؟"},{"id":"3881","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"9","aya_no":"93","aya_text":"فَرَاغَ عَلَيۡهِمۡ ضَرۡبَۢا بِٱلۡيَمِينِ","aya_text_emlaey":"فراغ عليهم ضربا باليمين","aya_tafseer":"[93] فأقبل على آلهتهم يضربها ويكسِّرها بيده اليمنى؛ ليثبت لقومه خطأ عبادتهم لها."},{"id":"3882","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"94","aya_text":"فَأَقۡبَلُوٓاْ إِلَيۡهِ يَزِفُّونَ","aya_text_emlaey":"فأقبلوا إليه يزفون","aya_tafseer":"[94] فأقبلوا إليه يَعْدُون مسرعين غاضبين."},{"id":"3883","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"95","aya_text":"قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ","aya_text_emlaey":"قال أتعبدون ما تنحتون","aya_tafseer":"[95] فلقيهم إبراهيم بثبات قائلاً: كيف تعبدون أصناماً تنحتونها أنتم، وتصنعونها بأيديكم،"},{"id":"3884","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"96","aya_text":"وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ","aya_text_emlaey":"والله خلقكم وما تعملون","aya_tafseer":"[96] وتتركون عبادة ربكم الذي خلقكم، وخلق عملكم؟"},{"id":"3885","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"11","aya_no":"97","aya_text":"قَالُواْ ٱبۡنُواْ لَهُۥ بُنۡيَٰنٗا فَأَلۡقُوهُ فِي ٱلۡجَحِيمِ","aya_text_emlaey":"قالوا ابنوا له بنيانا فألقوه في الجحيم","aya_tafseer":"[97] فلما قامت عليهم الحجة لجؤوا إلى القوة، وقالوا: ابنوا له بنياناً، واملؤوه حطباً، ثم ألقوه فيه."},{"id":"3886","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"98","aya_text":"فَأَرَادُواْ بِهِۦ كَيۡدٗا فَجَعَلۡنَٰهُمُ ٱلۡأَسۡفَلِينَ","aya_text_emlaey":"فأرادوا به كيدا فجعلناهم الأسفلين","aya_tafseer":"[98] فأراد قوم إبراهيم به كيداً لإهلاكه، فجعلناهم المقهورين المغلوبين، وردَّ الله كيدهم في نحورهم، وجعل النار على إبراهيم برداً وسلاماً."},{"id":"3887","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"99","aya_text":"وَقَالَ إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ","aya_text_emlaey":"وقال إني ذاهب إلى ربي سيهدين","aya_tafseer":"[99] وقال إبراهيم: إني مهاجر إلى ربي من بلد قومي إلى حيث أتمكن من عبادة ربي؛ فإنه سيدلني على الخير في ديني ودنياي."},{"id":"3888","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"100","aya_text":"رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"رب هب لي من الصالحين","aya_tafseer":"[100] رب أعطني ولداً صالحاً."},{"id":"3889","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"101","aya_text":"فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ","aya_text_emlaey":"فبشرناه بغلام حليم","aya_tafseer":"[101] فأجبنا له دعوته، وبشَّرناه بغلام حليم، أي: يكون حليماً في كبره، وهو إسماعيل."},{"id":"3890","jozz":"23","page":"449","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"15","aya_no":"102","aya_text":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"فلما بلغ معه السعي قال يابني إني أرى في المنام أني أذبحك فانظر ماذا ترى قال ياأبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين","aya_tafseer":"[102] فلما كَبِر إسماعيل ومشى مع أبيه قال له أبوه: إني أرى في المنام أني أذبحك، فما رأيك؟ (ورؤيا الأنبياء حق) فقال إسماعيل مُرْضياً ربه، بارّاً بوالده، معيناً له على طاعة الله: أمض ما أمرك الله به مِن ذبحي، ستجدني -إن شاء الله- صابراً طائعاً محتسباً."},{"id":"3891","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"103","aya_text":"فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ","aya_text_emlaey":"فلما أسلما وتله للجبين","aya_tafseer":"[103] فلما استسلما لأمر الله وانقادا له، وألقى إبراهيم ابنه على جبينه -وهو جانب الجبهة- على الأرض؛ ليذبحه."},{"id":"3892","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"104","aya_text":"وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ","aya_text_emlaey":"وناديناه أن ياإبراهيم","aya_tafseer":"[104] ونادينا إبراهيم في تلك الحالة العصيبة: أن يا إبراهيم،"},{"id":"3893","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"105","aya_text":"قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"قد صدقت الرؤيا إنا كذلك نجزي المحسنين","aya_tafseer":"[105] قد فعلتَ ما أُمرت به وصَدَّقْتَ رؤياك، إنا كما جزيناك على تصديقك نجزي الذين أحسنوا مثلك، فنخلِّصهم من الشدائد في الدنيا والآخرة."},{"id":"3894","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"3","aya_no":"106","aya_text":"إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ","aya_text_emlaey":"إن هذا لهو البلاء المبين","aya_tafseer":"[106] إن الأمر بذبح ابنك هو الابتلاء الشاق الذي أبان عن صدق إيمانك."},{"id":"3895","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"107","aya_text":"وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ","aya_text_emlaey":"وفديناه بذبح عظيم","aya_tafseer":"[107] واستنقذنا إسماعيل، فجعلنا بديلاً عنه كبشاً عظيماً."},{"id":"3896","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"4","aya_no":"108","aya_text":"وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ","aya_text_emlaey":"وتركنا عليه في الآخرين","aya_tafseer":"[108] وأبقينا لإبراهيم ثناءً حسناً في الأمم بعده."},{"id":"3897","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"109","aya_text":"سَلَٰمٌ عَلَىٰٓ إِبۡرَٰهِيمَ","aya_text_emlaey":"سلام على إبراهيم","aya_tafseer":"[109] تحيةٌ لإبراهيم من عند الله، ودعاءٌ له بالسلامة من كل آفة."},{"id":"3898","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"5","aya_no":"110","aya_text":"كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"كذلك نجزي المحسنين","aya_tafseer":"[110] كما جزينا إبراهيم على طاعته لنا وامتثاله أمرنا، نجزي المحسنين من عبادنا."},{"id":"3899","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"111","aya_text":"إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إنه من عبادنا المؤمنين","aya_tafseer":"[111] إنه من عبادنا المؤمنين الذين أعطَوا العبودية حقها."},{"id":"3900","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"6","aya_no":"112","aya_text":"وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"وبشرناه بإسحاق نبيا من الصالحين","aya_tafseer":"[112] وبشَّرنا إبراهيم بولده إسحاق نبيّاً من الصالحين؛ جزاء له على صبره ورضاه بأمر ربه، وطاعته له."},{"id":"3901","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"7","aya_no":"113","aya_text":"وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ","aya_text_emlaey":"وباركنا عليه وعلى إسحاق ومن ذريتهما محسن وظالم لنفسه مبين","aya_tafseer":"[113] وأنزلنا عليهما البركة. ومِن ذريتهما من هو مطيع لربه، محسن لنفسه، ومَن هو ظالم لها ظلماً بيِّناً بكفره ومعصيته."},{"id":"3902","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"8","aya_no":"114","aya_text":"وَلَقَدۡ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ","aya_text_emlaey":"ولقد مننا على موسى وهارون","aya_tafseer":"[114] ولقد مننَّا على موسى وهارون بالنبوة والرسالة،"},{"id":"3903","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"9","aya_no":"115","aya_text":"وَنَجَّيۡنَٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ ٱلۡعَظِيمِ","aya_text_emlaey":"ونجيناهما وقومهما من الكرب العظيم","aya_tafseer":"[115] ونجيناهما وقومهما من الغرق، وما كانوا فيه من عبودية ومَذلَّة."},{"id":"3904","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"116","aya_text":"وَنَصَرۡنَٰهُمۡ فَكَانُواْ هُمُ ٱلۡغَٰلِبِينَ","aya_text_emlaey":"ونصرناهم فكانوا هم الغالبين","aya_tafseer":"[116] ونصرناهم، فكانت لهم العزة والنصرة والغلبة على فرعون وآله."},{"id":"3905","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"10","aya_no":"117","aya_text":"وَءَاتَيۡنَٰهُمَا ٱلۡكِتَٰبَ ٱلۡمُسۡتَبِينَ","aya_text_emlaey":"وآتيناهما الكتاب المستبين","aya_tafseer":"[117] وآتيناهما التوراة البينة،"},{"id":"3906","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"118","aya_text":"وَهَدَيۡنَٰهُمَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ","aya_text_emlaey":"وهديناهما الصراط المستقيم","aya_tafseer":"[118] وهديناهما الطريق المستقيم الذي لا اعوجاج فيه، وهو الإسلام دين الله الذي ابتعث به أنبياءه،"},{"id":"3907","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"119","aya_text":"وَتَرَكۡنَا عَلَيۡهِمَا فِي ٱلۡأٓخِرِينَ","aya_text_emlaey":"وتركنا عليهما في الآخرين","aya_tafseer":"[119] وأبقينا لهما ثناءً حسناً وذكراً جميلاً فيمن بعدهما."},{"id":"3908","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"12","aya_no":"120","aya_text":"سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ","aya_text_emlaey":"سلام على موسى وهارون","aya_tafseer":"[120] تحيةٌ لموسى وهارون من عند الله، وثناءٌ ودعاءٌ لهما بالسلامة من كل آفة،"},{"id":"3909","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"121","aya_text":"إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"إنا كذلك نجزي المحسنين","aya_tafseer":"[121] كما جزيناهما الجزاء الحسن نجزي المحسنين من عبادنا المخلصين لنا بالصدق والإيمان والعمل."},{"id":"3910","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"13","aya_no":"122","aya_text":"إِنَّهُمَا مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إنهما من عبادنا المؤمنين","aya_tafseer":"[122] . إنهما من عبادنا الراسخين في الإيمان."},{"id":"3911","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"123","aya_text":"وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"وإن إلياس لمن المرسلين","aya_tafseer":"[123] وإن عبدنا إلياس لمن الذين أكرمناهم بالنبوة والرسالة،"},{"id":"3912","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"124","aya_text":"إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ","aya_text_emlaey":"إذ قال لقومه ألا تتقون","aya_tafseer":"[124] ، إذ قال لقومه من بني إسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره،"},{"id":"3913","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"15","aya_no":"125","aya_text":"أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ","aya_text_emlaey":"أتدعون بعلا وتذرون أحسن الخالقين","aya_tafseer":"[125] كيف تعبدون صنماً ضعيفاً مخلوقاً، وتتركون أحسنَ الخالقين -المتصفَ بأحسن الصفات وأكملها، فلا تعبدونه-"},{"id":"3914","jozz":"23","page":"450","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"126","aya_text":"ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"الله ربكم ورب آبائكم الأولين","aya_tafseer":"[126] اللهَ ربَّكم الذي خلقكم، وخلق آباءكم الماضين قبلكم؟"},{"id":"3915","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"127","aya_text":"فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ","aya_text_emlaey":"فكذبوه فإنهم لمحضرون","aya_tafseer":"[127] فكذب قوم إلياس نبيهم، فليجمعنهم الله يوم القيامة للحساب والعقاب،"},{"id":"3916","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"128","aya_text":"إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ","aya_text_emlaey":"إلا عباد الله المخلصين","aya_tafseer":"[128] إلا عباد الله الذين أخلصوا دينهم لله، فإنهم ناجون من عذابه."},{"id":"3917","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"129","aya_text":"وَتَرَكۡنَا عَلَيۡهِ فِي ٱلۡأٓخِرِينَ","aya_text_emlaey":"وتركنا عليه في الآخرين","aya_tafseer":"[129] وجعلنا لإلياس ثناءً جميلاً في الأمم بعده."},{"id":"3918","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"130","aya_text":"سَلَٰمٌ عَلَىٰٓ إِلۡ يَاسِينَ","aya_text_emlaey":"سلام على إل ياسين","aya_tafseer":"[130] تحية من الله، وثناءٌ على إلياس."},{"id":"3919","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"3","aya_no":"131","aya_text":"إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","aya_text_emlaey":"إنا كذلك نجزي المحسنين","aya_tafseer":"[131] وكما جزينا إلياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين"},{"id":"3920","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"3","line_end":"3","aya_no":"132","aya_text":"إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إنه من عبادنا المؤمنين","aya_tafseer":"[132] إنه من عباد الله المؤمنين المخلصين له العاملين بأوامره."},{"id":"3921","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"133","aya_text":"وَإِنَّ لُوطٗا لَّمِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"وإن لوطا لمن المرسلين","aya_tafseer":"[133] وإن عبدنا لوطاً اصطفيناه، فجعلناه من المرسلين،"},{"id":"3922","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"134","aya_text":"إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ","aya_text_emlaey":"إذ نجيناه وأهله أجمعين","aya_tafseer":"[134] إذ نجيناه وأهله أجمعين من العذاب،"},{"id":"3923","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"135","aya_text":"إِلَّا عَجُوزٗا فِي ٱلۡغَٰبِرِينَ","aya_text_emlaey":"إلا عجوزا في الغابرين","aya_tafseer":"[135] إلا عجوزاً هَرِمة، هي زوجته، هلكت مع الذين هلكوا من قومها لكفرها."},{"id":"3924","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"136","aya_text":"ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ","aya_text_emlaey":"ثم دمرنا الآخرين","aya_tafseer":"[136] ثم أهلكنا الباقين المكذبين من قومه."},{"id":"3925","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"6","aya_no":"137","aya_text":"وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ","aya_text_emlaey":"وإنكم لتمرون عليهم مصبحين","aya_tafseer":"[137] وإنكم -يا أهل «مكة»- لتمرون في أسفاركم على منازل قوم لوط وآثارهم وقت الصباح،"},{"id":"3926","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"138","aya_text":"وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"وبالليل أفلا تعقلون","aya_tafseer":"[138] وتمرون عليها ليلاً. أفلا تعقلون، فتخافوا أن يصيبكم مثل ما أصابهم؟"},{"id":"3927","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"7","aya_no":"139","aya_text":"وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"وإن يونس لمن المرسلين","aya_tafseer":"[139] وإن عبدنا يونس اصطفيناه وجعلناه من المرسلين،"},{"id":"3928","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"140","aya_text":"إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ","aya_text_emlaey":"إذ أبق إلى الفلك المشحون","aya_tafseer":"[140] إذ هرب من بلده غاضباً على قومه، وركب سفينة مملوءة ركاباً وأمتعة."},{"id":"3929","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"141","aya_text":"فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ","aya_text_emlaey":"فساهم فكان من المدحضين","aya_tafseer":"[141] وأحاطت بها الأمواج العظيمة، فاقترع ركاب السفينة لتخفيف الحمولة خوف الغرق، فكان يونس من المغلوبين بالقُرْعة."},{"id":"3930","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"142","aya_text":"فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ","aya_text_emlaey":"فالتقمه الحوت وهو مليم","aya_tafseer":"[142] فأُلقي في البحر، فابتلعه الحوت، ويونس عليه السلام آتٍ بما يُلام عليه."},{"id":"3931","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"143","aya_text":"فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ","aya_text_emlaey":"فلولا أنه كان من المسبحين","aya_tafseer":"[143] فلولا ما تقدَّم له من كثرة العبادة والعمل الصالح قبل وقوعه في بطن الحوت، وتسبيحه، وهو في بطن الحوت بقوله:لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ؛"},{"id":"3932","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"10","aya_no":"144","aya_text":"لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","aya_text_emlaey":"للبث في بطنه إلى يوم يبعثون","aya_tafseer":"[144] لمكث في بطن الحوت، وصار له قبراً إلى يوم القيامة."},{"id":"3933","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"145","aya_text":"۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ","aya_text_emlaey":"فنبذناه بالعراء وهو سقيم","aya_tafseer":"[145] فطرحناه من بطن الحوت، وألقيناه في أرض خالية عارية من الشجر والبناء، وهو ضعيف البدن."},{"id":"3934","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"11","aya_no":"146","aya_text":"وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ","aya_text_emlaey":"وأنبتنا عليه شجرة من يقطين","aya_tafseer":"[146] وأنبتنا عليه شجرة من القَرْع تظلُّه، وينتفع بها."},{"id":"3935","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"12","aya_no":"147","aya_text":"وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ","aya_text_emlaey":"وأرسلناه إلى مائة ألف أو يزيدون","aya_tafseer":"[147] وأرسلناه إلى مائة ألف من قومه بل يزيدون،"},{"id":"3936","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"148","aya_text":"فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ","aya_text_emlaey":"فآمنوا فمتعناهم إلى حين","aya_tafseer":"[148] فصدَّقوا وعملوا بما جاء به، فمتعناهم بحياتهم إلى وقت بلوغ آجالهم."},{"id":"3937","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"13","aya_no":"149","aya_text":"فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ","aya_text_emlaey":"فاستفتهم ألربك البنات ولهم البنون","aya_tafseer":"[149] فاسأل -أيها الرسول- قومك: كيف جعلوا لله البنات اللاتي يكرهونهنَّ، ولأنفسهم البنين الذين يريدونهم؟"},{"id":"3938","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"14","aya_no":"150","aya_text":"أَمۡ خَلَقۡنَا ٱلۡمَلَٰٓئِكَةَ إِنَٰثٗا وَهُمۡ شَٰهِدُونَ","aya_text_emlaey":"أم خلقنا الملائكة إناثا وهم شاهدون","aya_tafseer":"[150] واسألهم أخَلَقْنا الملائكة إناثاً، وهم حاضرون؟"},{"id":"3939","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"151","aya_text":"أَلَآ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَيَقُولُونَ","aya_text_emlaey":"ألا إنهم من إفكهم ليقولون","aya_tafseer":"[151] وإنَّ مِن كذبهم قولهم:"},{"id":"3940","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"15","aya_no":"152","aya_text":"وَلَدَ ٱللَّهُ وَإِنَّهُمۡ لَكَٰذِبُونَ","aya_text_emlaey":"ولد الله وإنهم لكاذبون","aya_tafseer":"[152] ولَد الله، وإنهم لكاذبون؛ لأنهم يقولون ما لا يعلمون."},{"id":"3941","jozz":"23","page":"451","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"153","aya_text":"أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِينَ","aya_text_emlaey":"أصطفى البنات على البنين","aya_tafseer":"[153] لأي شيء يختار الله البنات دون البنين؟"},{"id":"3942","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"154","aya_text":"مَا لَكُمۡ كَيۡفَ تَحۡكُمُونَ","aya_text_emlaey":"ما لكم كيف تحكمون","aya_tafseer":"[154] بئس الحكم ما تحكمونه -أيها القوم- أن يكون لله البنات ولكم البنون، وأنتم لا ترضون البنات لأنفسكم."},{"id":"3943","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"1","aya_no":"155","aya_text":"أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"أفلا تذكرون","aya_tafseer":"[155] أفلا تذكرون أنه لا يجوز ولا ينبغي أن يكون له ولد؟ تعالى الله عن ذلك علوّاً كبيراً."},{"id":"3944","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"1","line_end":"2","aya_no":"156","aya_text":"أَمۡ لَكُمۡ سُلۡطَٰنٞ مُّبِينٞ","aya_text_emlaey":"أم لكم سلطان مبين","aya_tafseer":"[156] بل ألكم حجة بيِّنة على قولكم وافترائكم؟"},{"id":"3945","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"2","aya_no":"157","aya_text":"فَأۡتُواْ بِكِتَٰبِكُمۡ إِن كُنتُمۡ صَٰدِقِينَ","aya_text_emlaey":"فأتوا بكتابكم إن كنتم صادقين","aya_tafseer":"[157] إن كانت لكم حجة في كتاب من عند الله فأتوا بها، إن كنتم صادقين في قولكم؟"},{"id":"3946","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"2","line_end":"3","aya_no":"158","aya_text":"وَجَعَلُواْ بَيۡنَهُۥ وَبَيۡنَ ٱلۡجِنَّةِ نَسَبٗاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ","aya_text_emlaey":"وجعلوا بينه وبين الجنة نسبا ولقد علمت الجنة إنهم لمحضرون","aya_tafseer":"[158] وجعل المشركون بين الله والملائكة قرابة ونسباً، ولقد علمت الملائكة أن المشركين محضرون للعذاب يوم القيامة."},{"id":"3947","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"159","aya_text":"سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ","aya_text_emlaey":"سبحان الله عما يصفون","aya_tafseer":"[159] تنزَّه الله عن كل ما لا يليق به ممَّا يصفه به الكافرون."},{"id":"3948","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"4","line_end":"4","aya_no":"160","aya_text":"إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ","aya_text_emlaey":"إلا عباد الله المخلصين","aya_tafseer":"[160] لكن عباد الله الذين اصطفاهم لعبادته لا يصفونه إلا بما يليق بجلاله سبحانه."},{"id":"3949","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"161","aya_text":"فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ","aya_text_emlaey":"فإنكم وما تعبدون","aya_tafseer":"[161] فإنكم -أيها المشركون بالله- وما تعبدون من دون الله من آلهة،"},{"id":"3950","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"5","line_end":"5","aya_no":"162","aya_text":"مَآ أَنتُمۡ عَلَيۡهِ بِفَٰتِنِينَ","aya_text_emlaey":"ما أنتم عليه بفاتنين","aya_tafseer":"[162] ما أنتم بمضلِّين أحداً"},{"id":"3951","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"163","aya_text":"إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِيمِ","aya_text_emlaey":"إلا من هو صال الجحيم","aya_tafseer":"[163] إلا مَن قدَّر الله عز وجل عليه أن يَصْلَى الجحيم؛ لكفره وظلمه."},{"id":"3952","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"6","line_end":"6","aya_no":"164","aya_text":"وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٞ مَّعۡلُومٞ","aya_text_emlaey":"وما منا إلا له مقام معلوم","aya_tafseer":"[164] قالت الملائكة: وما منا أحدٌ إلا له مقام في السماء معلوم،"},{"id":"3953","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"165","aya_text":"وَإِنَّا لَنَحۡنُ ٱلصَّآفُّونَ","aya_text_emlaey":"وإنا لنحن الصافون","aya_tafseer":"[165] وإنا لنحن الواقفون صفوفاً في عبادة الله وطاعته،"},{"id":"3954","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"7","line_end":"7","aya_no":"166","aya_text":"وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ","aya_text_emlaey":"وإنا لنحن المسبحون","aya_tafseer":"[166] وإنا لنحن المنزِّهون الله عن كل ما لا يليق به."},{"id":"3955","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"167","aya_text":"وَإِن كَانُواْ لَيَقُولُونَ","aya_text_emlaey":"وإن كانوا ليقولون","aya_tafseer":"[167] وإن كفار «مكة» ليقولون قبل بعثتك -أيها الرسول-"},{"id":"3956","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"8","line_end":"8","aya_no":"168","aya_text":"لَوۡ أَنَّ عِندَنَا ذِكۡرٗا مِّنَ ٱلۡأَوَّلِينَ","aya_text_emlaey":"لو أن عندنا ذكرا من الأولين","aya_tafseer":"[168] لو جاءنا من الكتب والأنبياء ما جاء الأولين قبلنا،"},{"id":"3957","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"169","aya_text":"لَكُنَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِينَ","aya_text_emlaey":"لكنا عباد الله المخلصين","aya_tafseer":"[169] لكنا عباد الله الصادقين في الإيمان، المخلَصين في العبادة."},{"id":"3958","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"9","aya_no":"170","aya_text":"فَكَفَرُواْ بِهِۦۖ فَسَوۡفَ يَعۡلَمُونَ","aya_text_emlaey":"فكفروا به فسوف يعلمون","aya_tafseer":"[170] فلما جاءهم ذكر الأولين، وعلم الآخرين، وأكمل الكتب، وأفضل الرسل، وهو محمد -صلى الله عليه وسلم-، كفروا به، فسوف يعلمون ما لهم من العذاب في الآخرة."},{"id":"3959","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"9","line_end":"10","aya_no":"171","aya_text":"وَلَقَدۡ سَبَقَتۡ كَلِمَتُنَا لِعِبَادِنَا ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"ولقد سبقت كلمتنا لعبادنا المرسلين","aya_tafseer":"[171] ولقد سبقت كلمتنا -التي لا مردَّ لها- لعبادنا المرسلين،"},{"id":"3960","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"10","line_end":"10","aya_no":"172","aya_text":"إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ","aya_text_emlaey":"إنهم لهم المنصورون","aya_tafseer":"[172] أن لهم النصرة على أعدائهم بالحجة والقوة،"},{"id":"3961","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"173","aya_text":"وَإِنَّ جُندَنَا لَهُمُ ٱلۡغَٰلِبُونَ","aya_text_emlaey":"وإن جندنا لهم الغالبون","aya_tafseer":"[173] وأن جندنا المجاهدين في سبيلنا لهم الغالبون لأعدائهم في كل مقام باعتبار العاقبة والمآل."},{"id":"3962","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"11","aya_no":"174","aya_text":"فَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينٖ","aya_text_emlaey":"فتول عنهم حتى حين","aya_tafseer":"[174] فأعرض -أيها الرسول- عَمَّن عاند، ولم يقبل الحق حتى تنقضي المدة التي أمهلهم فيها، ويأتي أمر الله بعذابهم،"},{"id":"3963","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"11","line_end":"12","aya_no":"175","aya_text":"وَأَبۡصِرۡهُمۡ فَسَوۡفَ يُبۡصِرُونَ","aya_text_emlaey":"وأبصرهم فسوف يبصرون","aya_tafseer":"[175] وأنظرهم وارتقب ماذا يحل بهم من العذاب بمخالفتك؟ فسوف يرون ما يحل بهم من عذاب الله."},{"id":"3964","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"12","aya_no":"176","aya_text":"أَفَبِعَذَابِنَا يَسۡتَعۡجِلُونَ","aya_text_emlaey":"أفبعذابنا يستعجلون","aya_tafseer":"[176] أفبنزول عذابنا بهم يستعجلونك أيها الرسول؟"},{"id":"3965","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"12","line_end":"13","aya_no":"177","aya_text":"فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَآءَ صَبَاحُ ٱلۡمُنذَرِينَ","aya_text_emlaey":"فإذا نـزل بساحتهم فساء صباح المنذرين","aya_tafseer":"[177] فإذا نزل عذابنا بهم، فبئس الصباح صباحهم."},{"id":"3966","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"13","aya_no":"178","aya_text":"وَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِينٖ","aya_text_emlaey":"وتول عنهم حتى حين","aya_tafseer":"[178] وأعرض عنهم حتى يأذن الله بعذابهم،"},{"id":"3967","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"13","line_end":"14","aya_no":"179","aya_text":"وَأَبۡصِرۡ فَسَوۡفَ يُبۡصِرُونَ","aya_text_emlaey":"وأبصر فسوف يبصرون","aya_tafseer":"[179] وأنظرهم فسوف يرون ما يحل بهم من العذاب والنكال."},{"id":"3968","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"14","line_end":"14","aya_no":"180","aya_text":"سُبۡحَٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا يَصِفُونَ","aya_text_emlaey":"سبحان ربك رب العزة عما يصفون","aya_tafseer":"[180] تنزَّه الله وتعالى رب العزة عما يصفه هؤلاء المفترون عليه."},{"id":"3969","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"181","aya_text":"وَسَلَٰمٌ عَلَى ٱلۡمُرۡسَلِينَ","aya_text_emlaey":"وسلام على المرسلين","aya_tafseer":"[181] وتحية الله الدائمة وثناؤه وأمانه لجميع المرسلين."},{"id":"3970","jozz":"23","page":"452","sura_no":"37","sura_name_en":"Aṣ-Ṣāffāt","sura_name_ar":"الصَّافَات ","line_start":"15","line_end":"15","aya_no":"182","aya_text":"وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","aya_text_emlaey":"والحمد لله رب العالمين","aya_tafseer":"[182] والحمد لله رب العالمين في الأولى والآخرة، فهو المستحق لذلك وحده لا شريك له."}]
